package org.chromium.lintsample;

/**
 * Stands in for aapt's generated R class: class and field names are resource names, which lint
 * matches to the sample's resources.
 */
public final class R {
    /** Ids. */
    public static final class id {
        public static final int sample_text = 0x7f010000;
        public static final int sample_image = 0x7f010001;
    }

    /** Layouts. */
    public static final class layout {
        public static final int sample = 0x7f020000;
    }

    /** Strings. */
    public static final class string {
        public static final int sample_format = 0x7f030000;
        public static final int sample_title = 0x7f030001;
    }

    /** Drawables. */
    public static final class drawable {
        public static final int ic_sample = 0x7f040000;
    }
}
